mapper.select:
SELECT tl.id, tl.type, tl.source_id, tl.target_id, tl.directed, tl.weight, tl.status, tl.version, tl.updated_at, tl.properties FROM topology_links tl
JOIN network_elements src ON src.id = source_id JOIN network_elements tgt ON tgt.id = target_id
WHERE ( tl.source_id IN
#{id}
OR tl.target_id IN
#{id}
)
AND src.type = ANY(#{types}::text[]) AND tgt.type = ANY(#{types}::text[])
ORDER BY tl.id LIMIT #{limit}
